import type { TurnCompleteInput } from 'claude-code'

/**
 * The host-neutral contract `mentions.ingest` takes; `src/mentions-types.ts`
 * owns it. Restated here because a hooks module cannot import application code.
 */
export type MentionMessage = {
  workspaceRoot: string
  agent: 'claude'
  sessionId: string
  messageId: string
  text: string
}

/**
 * A folder list as configured (the `workspaces` option or
 * `PI_OUTLINER_MENTIONS_WORKSPACES`): one absolute folder or several,
 * separated by ':' or ','. Trailing slashes are dropped so `/a/b/` matches a
 * cwd of `/a/b`. An entry names a folder only; any other entry is an error,
 * never skipped. In folder mode the list opts folders out; in allowlist mode
 * it is the only folders that feed an outline (`mentionsModeOf`).
 */
export function workspacesOf(value: unknown, home?: string): string[] {
  const parts = Array.isArray(value) ? value : typeof value === 'string' ? value.split(/[:,]/) : []
  return parts.flatMap(part => {
    if (typeof part !== 'string') throw Error(`Outliner workspaces entry ${JSON.stringify(part)} is not a folder path`)
    const typed = part.trim()
    // `~` and `~/…` are written by people; expand them when the home folder is known.
    const entry = home && (typed === '~' || typed.startsWith('~/')) ? home.replace(/\/+$/, '') + typed.slice(1) : typed
    if (entry === '') return []
    if (!entry.startsWith('/') || entry.includes('=')) {
      throw Error(`Outliner workspaces entry "${entry}" is not an absolute folder; list folders only, and bind a folder to an outline in its client.json (the choose-outline action)`)
    }
    return [entry.replace(/(?<=.)\/+$/, '')]
  })
}

/**
 * The option when it names at least one folder, otherwise the environment
 * variable. Claude Code passes an unset string option as '', so an empty
 * option cannot be told from an unset one and never overrides the environment.
 */
export function effectiveWorkspaces(option: unknown, environment: string | undefined, home?: string): string[] {
  const configured = workspacesOf(option, home)
  return configured.length > 0 ? configured : workspacesOf(environment, home)
}

/**
 * How a session's folder finds its outline:
 *
 * - `folder`: the nearest folder bound to an outline, the way every Outliner
 *   client resolves it (`bound-folder`: a `client.json`, or an outline root the
 *   host serves). The folder list opts folders out. An unbound folder feeds
 *   nothing; it never falls back to a default outline.
 * - `allowlist`: only the listed folders, as before folder mode (the strict mode).
 */
export type MentionsMode = 'folder' | 'allowlist'

/**
 * The `mode` option when set, otherwise `PI_OUTLINER_MENTIONS_MODE`; neither:
 * `folder`, unless folders are listed. A list with no mode is a setup from
 * before folder mode, where the list was an allowlist, so it keeps meaning
 * exactly that: only the folders someone chose feed. Any other value is an error.
 */
export function mentionsModeOf(option: unknown, environment: string | undefined, listed: readonly string[] = []): MentionsMode {
  const typed = typeof option === 'string' && option.trim() !== '' ? option.trim() : (environment ?? '').trim()
  if (typed === '' && listed.length > 0) return 'allowlist'
  if (typed === '' || typed === 'folder' || typed === 'allowlist') return typed === 'allowlist' ? 'allowlist' : 'folder'
  throw Error(`Outliner mentions mode "${typed}" is neither folder nor allowlist`)
}

/**
 * The folder a session's Outliner CLI runs start from. A bound folder (folder
 * mode) is `pinned` to the outline `bound-folder` found, `outline` when it
 * names a host outline: its CLI runs go there whatever Claude's environment
 * says. A strict-mode folder is the CLI's to resolve, as before folder mode.
 */
export type Workspace = { root: string; outline?: string; pinned?: true }

/**
 * The environment an Outliner CLI run gets for a workspace: its folder and,
 * when pinned, the outline that bound it, blanking an inherited
 * OUTLINER_OUTLINE or OUTLINER_CONFIG_PATH so the write lands where the folder
 * was found bound (`resolveClientPaths` reads an empty one as unset).
 */
export function workspaceEnvOf(workspace: Workspace): Record<string, string> {
  return {
    OUTLINER_WORKSPACE_ROOT: workspace.root,
    ...(workspace.pinned ? { OUTLINER_OUTLINE: workspace.outline ?? '', OUTLINER_CONFIG_PATH: '' } : {}),
  }
}

/**
 * The bound folder in `bound-folder`'s answer for `cwd`, or null: unbound, or
 * an answer that is not one (a folder that does not contain `cwd` is not).
 */
export function boundWorkspaceOf(stdout: string, cwd: string): Workspace | null {
  let answer: unknown
  try { answer = JSON.parse(stdout) } catch { return null }
  if (!answer || typeof answer !== 'object') return null
  const { bound, source, folder, outline } = answer as Record<string, unknown>
  if (bound !== true || typeof folder !== 'string') return null
  const root = absolutePath(folder)
  if (root === null || workspaceForCwd(cwd, [root]) !== root) return null
  const named = typeof outline === 'string' && outline !== '' ? outline : undefined
  if (source === 'host-root') return named ? { root, outline: named, pinned: true } : null
  // A client.json naming a host outline is pinned to it; a local or remote choice is the folder's config to resolve.
  if (source !== 'client') return null
  const { mode } = answer as Record<string, unknown>
  return mode === 'host' ? (named ? { root, outline: named, pinned: true } : null) : { root, pinned: true }
}

/**
 * The workspace a session in `cwd` feeds, or null. In folder mode a listed
 * folder (or one inside it) is opted out, and otherwise the bound folder wins;
 * in allowlist mode the nearest listed folder, bound or not.
 */
export function sessionWorkspaceOf(
  cwd: string,
  mode: MentionsMode,
  listed: readonly string[],
  bound: Workspace | null,
): Workspace | null {
  const nearestListed = workspaceForCwd(cwd, listed)
  if (mode === 'allowlist') return nearestListed === null ? null : { root: nearestListed }
  return nearestListed === null ? bound : null
}

/**
 * The reason in an Outliner CLI failure's stderr: Bun prints the thrown
 * error's source excerpt, then `error: <message>`, its stack and a `Bun v…`
 * trailer, so the last line never says why. Falls back to the last line that
 * is not stack or trailer; '' when nothing is left.
 */
export function failureReasonOf(stderr: string): string {
  const lines = stderr.split('\n').map(line => line.trim()).filter(Boolean)
  const error = lines.findLast(line => line.startsWith('error: '))
  if (error) return error.slice('error: '.length)
  return lines.findLast(line => !/^at\s|^Bun v\d/.test(line)) ?? ''
}

/**
 * Which completed turns reach Recent Mentions: the main loop's own answers,
 * never a subagent's run, an interruption, a refusal or an error.
 */
export function isIngestible(e: TurnCompleteInput): boolean {
  return e.agentId === undefined && e.reason === 'answer' && e.answer.trim() !== ''
}

// Lexical POSIX paths: no host filesystem access or Git-root assumptions.
function absolutePath(path: string): string | null {
  if (!path.startsWith('/')) return null
  const parts: string[] = []
  for (const part of path.split('/')) {
    if (part === '..') parts.pop()
    else if (part !== '' && part !== '.') parts.push(part)
  }
  return '/' + parts.join('/')
}

/** Nested configured roots own their descendants; siblings never match a prefix. */
export function workspaceForCwd(cwd: string, workspaces: readonly string[]): string | null {
  const path = absolutePath(cwd)
  if (path === null) return null
  let nearest: string | null = null
  for (const workspace of workspaces) {
    const root = absolutePath(workspace)
    if (root === null) continue
    if ((path === root || path.startsWith(root === '/' ? '/' : root + '/')) &&
        (nearest === null || root.length > nearest.length)) nearest = root
  }
  return nearest
}

/**
 * The message for one completed turn in a session feeding `workspace`, or
 * null when the turn is not ingested or the session feeds none. The turn id
 * is the message identity, so a repeated delivery of the same turn
 * deduplicates in the service.
 */
export function mentionMessageOf(
  e: TurnCompleteInput,
  session: { id: string },
  workspace: Workspace | null,
): MentionMessage | null {
  if (!isIngestible(e) || workspace === null) return null
  return {
    workspaceRoot: workspace.root,
    agent: 'claude',
    sessionId: session.id,
    messageId: e.turnId,
    text: e.answer,
  }
}

files.hooks/references.ts:
/**
 * Outliner references in a Claude reply, made clickable. `Markdown` only draws
 * `https:`, `http:` and `file:` links as links, so each reference becomes an
 * https stand-in on the reserved `.invalid` domain, which never resolves: a
 * click the plugin does not take goes nowhere. The plugin maps it back to the
 * `pi-outliner://` URI the Outliner's own link navigation takes.
 */
const STAND_IN = 'https://pi-outliner.invalid/'

const UUID = '[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}'

/**
 * Code, existing links and URLs: never rewritten. An unclosed fence runs to the
 * end, as the renderer draws it.
 */
const PROTECTED = /```[\s\S]*?(?:```|$)|~~~[\s\S]*?(?:~~~|$)|`[^`\n]*`|!?\[[^\]\n]*\]\([^)\n]*\)|<[a-z][a-z0-9+.-]*:[^>\s]*>|\b[a-z][a-z0-9+.-]*:\/\/[^\s<>()]+/gi

export type Linkified = {
  /** The markdown to draw, references as stand-in links. */
  text: string
  /** Every stand-in href in `text`, once each: what `pressableLinks` takes. */
  hrefs: string[]
}

/**
 * `[[page]]`, `[[target|label]]`, `((uuid))`, `((uuid|label))` and bare Work
 * IDs with one of `prefixes`, rewritten as links outside protected ranges.
 */
export function linkifyReferences(text: string, prefixes: readonly string[]): Linkified {
  const hrefs = new Set<string>()
  const workIds = prefixes
    .filter(prefix => /^[A-Z][A-Z0-9]*$/.test(prefix))
    .map(prefix => `${prefix}-\\d+`)
  const reference = new RegExp(
    `\\[\\[([^\\[\\]|\\n]+)(?:\\|([^\\[\\]\\n]+))?\\]\\]` +
      `|\\(\\((${UUID})(?:\\|([^()\\n]+))?\\)\\)` +
      (workIds.length ? `|(?<![\\w/#-])(${workIds.join('|')})(?![\\w-])` : ''),
    'g',
  )
  const rewrite = (plain: string) =>
    plain.replace(reference, (whole, page?: string, pageLabel?: string, block?: string, blockLabel?: string, workId?: string) => {
      const [kind, value, label] = page
        ? ['page', page.trim(), pageLabel?.trim() || page.trim()]
        : block
          ? ['block', block.toLowerCase(), blockLabel?.trim() || whole]
          : ['work', workId!.toUpperCase(), workId!]
      const href = `${STAND_IN}${kind}/${encodeURIComponent(value)}`
      hrefs.add(href)
      return `[${label.replace(/[[\]\\]/g, '\\$&')}](${href})`
    })

  let out = ''
  let last = 0
  for (const match of text.matchAll(PROTECTED)) {
    out += rewrite(text.slice(last, match.index)) + match[0]
    last = match.index + match[0].length
  }
  out += rewrite(text.slice(last))
  return { text: out, hrefs: [...hrefs] }
}

/**
 * The `pi-outliner://` URI a stand-in href names, or null for any other link.
 */
export function outlinerUriOf(href: string): string | null {
  if (!href.startsWith(STAND_IN)) return null
  const [kind, value, ...rest] = href.slice(STAND_IN.length).split('/')
  if (rest.length || !value || !['block', 'page', 'work'].includes(kind!)) return null
  return `pi-outliner://${kind}/${value}`
}

export type OutlinerClient = {
  clientId: string
  role: string
  paneId: string
  contextId?: string
}

/**
 * Claude's own Outliner Detail: the live Detail whose browsing context is this
 * Claude session's id, which only a pane this session split carries. Null when
 * there is none, or its pane is gone (`paneTabs` holds the workspace's live
 * panes).
 */
export function scratchPaneOf(
  clients: readonly OutlinerClient[],
  paneTabs: ReadonlyMap<string, string>,
  sessionId: string,
): OutlinerClient | null {
  return clients.find(client =>
    client.role === 'detail' && client.contextId === sessionId && paneTabs.has(client.paneId)) ?? null
}

/**
 * The `pi-outliner://` URI for a reference as the model writes it: a Work ID,
 * `[[page]]`, `((uuid))`, a bare block UUID, a `pi-outliner://` URI, or else a
 * page address as given. Null for an empty reference.
 */
export function outlinerUriFor(reference: string): string | null {
  const text = reference.trim()
  if (!text) return null
  if (text.startsWith('pi-outliner://')) return text
  if (new RegExp(`^${UUID}$`).test(text)) return `pi-outliner://block/${text.toLowerCase()}`
  if (/^[A-Z][A-Z0-9]*-\d+$/.test(text)) return `pi-outliner://work/${text}`
  const { hrefs } = linkifyReferences(text, [])
  if (hrefs.length === 1 && /^(\[\[[^\]]+\]\]|\(\([^)]+\)\))$/.test(text)) return outlinerUriOf(hrefs[0]!)
  return `pi-outliner://page/${encodeURIComponent(text)}`
}

/** What a `pi-outliner://` URI names, as the person reads it: the Work ID, page name or block id. */
export function outlinerLabelOf(uri: string): string {
  return decodeURIComponent(uri.slice(uri.indexOf('/', 'pi-outliner://'.length) + 1))
}

/** The block id a `pi-outliner://block/…` URI names, lowercased; null for a page, Work ID or anything else. */
export function outlinerBlockIdOf(uri: string): string | null {
  return new RegExp(`^pi-outliner://block/(${UUID})$`).exec(uri)?.[1]?.toLowerCase() ?? null
}

/**
 * The reference the outline writes for a URI, the reverse of `outlinerUriFor`:
 * `((id))` for a block, `[[page]]` for a page, the Work ID itself.
 */
export function outlinerReferenceOf(uri: string): string {
  const block = outlinerBlockIdOf(uri)
  if (block) return `((${block}))`
  return uri.startsWith('pi-outliner://page/') ? `[[${outlinerLabelOf(uri)}]]` : outlinerLabelOf(uri)
}

/**
 * Whether a navigation failed only because its destination is mid-edit (or
 * holding a source selection): the Outliner protects it, and a new Detail is
 * the way round, never overriding the protection.
 */
export function isProtectedDestination(reason: string): boolean {
  return reason.startsWith('Destination is protected')
}

/**
 * The Herdr command that splits Claude's own Detail below `paneId` (the Claude
 * pane), unfocused, already showing the block. Its browsing context is the
 * session id, which is how `scratchPaneOf` finds it again.
 */
export function detailSplitArgv(split: {
  paneId: string
  workspace: string
  /** The outline, when the folder's own client.json doesn't name it (a root only the host records). */
  outline?: string
  sessionId: string
  blockId: string
  fragmentId?: string
}): string[] {
  const target = { kind: 'block', blockId: split.blockId, ...(split.fragmentId ? { fragmentId: split.fragmentId } : {}) }
  return [
    'herdr', 'plugin', 'pane', 'open',
    '--plugin', 'float.pi-outliner',
    '--entrypoint', 'detail',
    '--placement', 'split',
    '--target-pane', split.paneId,
    '--direction', 'down',
    '--no-focus',
    '--cwd', split.workspace,
    '--env', `OUTLINER_WORKSPACE_ROOT=${split.workspace}`,
    ...(split.outline ? ['--env', `OUTLINER_OUTLINE=${split.outline}`] : []),
    '--env', `OUTLINER_BROWSING_CONTEXT_ID=${split.sessionId}`,
    '--env', `OUTLINER_DETAIL_TARGET=${encodeURIComponent(JSON.stringify(target))}`,
  ]
}

files.hooks/outline-tools.ts:
/**
 * Outline and door tools for Claude (PIE-504), so an agent never hand-rolls a
 * script to read, edit or comment on a note, or to act in the door it runs in.
 *
 * - `outline_*`: each is one call to the installed CLI's `agent <operation>`
 *   (src/agent-tools.ts) with the tool's input as JSON on stdin. The service and
 *   that module own the rules; this file only names the operation and checks
 *   the input's shape.
 * - `door_*`: each is one `ep0ch` command on the session's EP0CH_CONTROL, the
 *   door this Claude runs in. They exist only when EP0CH_CONTROL is set. The
 *   door enforces its rules (an agent never takes the person's focus); its
 *   refusals come back as the tool's denial.
 *
 * Every write is `author: agent`, attributed to the actor `actorOf` picks.
 */

type Json = Record<string, unknown>

export interface OutlineToolDefinition {
  name: string
  description: string
  inputSchema: Json
  /** The CLI `agent` operation and its JSON input, or the reason the input is unusable. */
  command(input: Record<string, unknown>): { operation: string; input: Json } | string
}

const ACTOR = {
  type: 'string',
  description: 'Who this is attributed to. Leave it out: it defaults to OUTLINER_ACTOR, EP0CH_AGENT or claude-code.',
}
const REF = {
  type: 'string',
  description: 'The block: its id, ((id)), [[page]] or a Work ID (PIE-123). Never a title: find it with outline_find first.',
}
const EXPECTED = {
  type: 'integer',
  minimum: 1,
  description: 'The revision outline_read returned. A block that changed since is refused: read it again.',
}

/** A write's schema carries `actor`, the attribution override; a read's has none (outline_changes' `actor` is a filter). */
function schema(properties: Json, required: string[], writes = true): Json {
  return { type: 'object', properties: writes ? { ...properties, actor: ACTOR } : properties, required, additionalProperties: false }
}

/** The input without the actor, which travels as a CLI flag, and without keys left undefined. */
function inputOf(input: Record<string, unknown>, keys: readonly string[]): Json {
  const out: Json = {}
  for (const key of keys) if (input[key] !== undefined) out[key] = input[key]
  return out
}

const nonEmpty = (value: unknown): value is string => typeof value === 'string' && value.trim() !== ''

export const OUTLINE_TOOLS: readonly OutlineToolDefinition[] = [
  {
    name: 'outline_read',
    description:
      "Read a note: its full text (never just the title), properties, revision, who last wrote it and when, and its " +
      'children to `depth` levels (default 1), at most `limit` descendants (default 50), each with full text. ' +
      '`complete` says whether anything was left out; a child with `more` has unread children. Read before you ' +
      'edit: outline_edit and outline_patch need the revision this returns.',
    inputSchema: schema({
      ref: REF,
      depth: { type: 'integer', minimum: 0, maximum: 6 },
      limit: { type: 'integer', minimum: 0, maximum: 500 },
    }, ['ref'], false),
    command(input) {
      if (!nonEmpty(input.ref)) return 'Give the ref: a block id, ((id)), [[page]] or Work ID.'
      return { operation: 'read', input: inputOf(input, ['ref', 'depth', 'limit']) }
    },
  },
  {
    name: 'outline_find',
    description:
      'Find blocks by text, a property (`key=value`, or `key`), a property key (hasKey), a query in the saved-view ' +
      'grammar (`type=roadmap-item AND work-stage=doing`), or a saved view. text, property, hasKey, query and under ' +
      'combine; view stands alone. Returns rows (id, title, revision); read one with outline_read.',
    inputSchema: schema({
